$ErrorActionPreference = 'Stop'
$taskQtEnv = (Get-Content build/qt68-ci-venv.txt -Raw).Trim()
$taskRuntimes = @(
    @{ Name = 'modern'; Program = 'py'; Prefix = @('-3') },
    @{ Name = 'qt68'; Program = "$taskQtEnv/Scripts/python.exe"; Prefix = @() }
)
Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue
$taskRecords = @()
foreach ($runtime in $taskRuntimes) {
    foreach ($operation in @('noop', 'headers', 'unit', 'labels', 'keeper', 'language')) {
        $arguments = $runtime.Prefix + @('-m', 'tools.measure_grouped_layout', $operation)
        $line = & $runtime.Program @arguments
        if ($LASTEXITCODE -ne 0) { throw "Probe failed: $($runtime.Name)/$operation" }
        $entry = $line | ConvertFrom-Json
        $entry | Add-Member -NotePropertyName runtime_label -NotePropertyValue $runtime.Name
        $taskRecords += $entry
        $entry | Select-Object runtime_label, operation, instrumented, handler_ms, @{n='one_event_pass_ms';e={$_.event_passes[0].cumulative_ms}}, verified | ConvertTo-Json -Compress
    }
    for ($repeat = 1; $repeat -le 3; $repeat++) {
        foreach ($operation in @('noop', 'headers', 'language')) {
            $arguments = $runtime.Prefix + @('-m', 'tools.measure_grouped_layout', $operation, '--no-counts')
            $line = & $runtime.Program @arguments
            if ($LASTEXITCODE -ne 0) { throw "Probe failed: $($runtime.Name)/$operation/$repeat" }
            $entry = $line | ConvertFrom-Json
            $entry | Add-Member -NotePropertyName runtime_label -NotePropertyValue $runtime.Name
            $entry | Add-Member -NotePropertyName repeat -NotePropertyValue $repeat
            $taskRecords += $entry
            $entry | Select-Object runtime_label, operation, instrumented, repeat, handler_ms, @{n='one_event_pass_ms';e={$_.event_passes[0].cumulative_ms}}, verified | ConvertTo-Json -Compress
        }
    }
    $taskRecords | ConvertTo-Json -Depth 12 | Set-Content build/grouped-layout-final-observations.json -Encoding utf8
}

