"""Diagnostic decomposition using the previously retained owned display harness."""
import json
from pathlib import Path
import sys
import time

source = Path('build/measure_grouped_display.py').read_text(encoding='utf-8')
setup = source.split('started = time.perf_counter()')[0]
imports, construction = setup.split('app = QApplication([])', 1)
exec(compile(imports, 'build/measure_grouped_display.py', 'exec'))
from PySide6.QtCore import QEvent, QModelIndex, QObject
from je_file_tree.gui.grouped_list import GroupedListModel
from PySide6.QtWidgets import QTreeView

calls = {'index': 0, 'flags': 0}
layouts = []


class WatchedView(QTreeView):
    def doItemsLayout(self):
        before = dict(calls)
        started = time.perf_counter()
        super().doItemsLayout()
        layouts.append({'ms': (time.perf_counter() - started) * 1000,
                        'calls': {key: calls[key] - before[key] for key in calls}})


class CountedModel(GroupedListModel):
    def index(self, row, column, parent=QModelIndex()):
        calls['index'] += 1
        if '--direct-index' in sys.argv:
            if row < 0 or not 0 <= column < 4:
                return QModelIndex()
            if not parent.isValid():
                return self.createIndex(row, column, 0) if row < len(self._groups) else QModelIndex()
            if parent.column() != 0 or parent.internalId() != 0:
                return QModelIndex()
            group_row = parent.row()
            return (self.createIndex(row, column, group_row + 1)
                    if row < len(self._groups[group_row].nodes) else QModelIndex())
        return super().index(row, column, parent)

    def flags(self, index):
        calls['flags'] += 1
        return super().flags(index)

    def sibling(self, row, column, index):
        if '--direct-sibling' not in sys.argv:
            return super().sibling(row, column, index)
        if row < 0 or not 0 <= column < 4 or not index.isValid() or index.model() is not self:
            return QModelIndex()
        group_id = index.internalId()
        count = len(self._groups[group_id - 1].nodes) if group_id else len(self._groups)
        return self.createIndex(row, column, group_id) if row < count else QModelIndex()


cleanup_panel.grouped_list.GroupedListModel = CountedModel
if '--watch-view' in sys.argv:
    cleanup_panel.grouped_list.QTreeView = WatchedView
exec(compile('app = QApplication([])' + construction, 'build/measure_grouped_display.py', 'exec'))
stage = sys.argv[3]
events = []


class Watch(QObject):
    def eventFilter(self, watched, event):
        if event.type() in (QEvent.Resize, QEvent.LayoutRequest, QEvent.FontChange, QEvent.StyleChange):
            events.append((watched.objectName(), event.type().name))
        return False


watch = Watch()
for name, widget in [('panel', panel), ('view', panel.view), ('viewport', panel.view.viewport()),
                     ('header', panel.view.header())]:
    widget.setObjectName(name)
    widget.installEventFilter(watch)


def geometry():
    return {'view': panel.view.geometry().getRect(), 'viewport': panel.view.viewport().geometry().getRect(),
            'header': panel.view.header().geometry().getRect(),
            'columns': [panel.view.columnWidth(column) for column in range(4)],
            'row_height': panel.view.rowHeight(panel.model.index(0, 0))}


before = geometry()
calls.update(index=0, flags=0)
layouts.clear()
i18n.set_language('zh-TW')
started = time.perf_counter()
if stage == 'headers':
    panel.model.headerDataChanged.emit(Qt.Horizontal, 0, 3)
elif stage == 'keepers':
    for row, group in enumerate(panel.model._groups):
        if group.kept is not None:
            parent = panel.model.index(row, 0)
            for position, node in enumerate(group.nodes):
                if node is group.kept:
                    index = panel.model.index(position, 0, parent)
                    panel.model.dataChanged.emit(index, index, [Qt.DisplayRole])
elif stage == 'labels':
    if kind == 'cleanup':
        panel.model.set_group_labels(panel._group_labels())
    else:
        panel._refresh_group_labels()
elif stage == 'controls':
    panel.model.retranslate = lambda: None
    panel.model.set_group_labels = lambda _labels: None
    panel.retranslate()
elif stage == 'all':
    panel.retranslate()
elif stage != 'nothing':
    raise ValueError(stage)
handler = (time.perf_counter() - started) * 1000
handler_calls = dict(calls)
app.processEvents()
settled = (time.perf_counter() - started) * 1000
event_calls = dict(calls)
after = geometry()
print(json.dumps({'kind': kind, 'stage': stage, 'pyside6': pyside6_version, 'platform': app.platformName(),
                  'handler_ms': handler, 'one_event_pass_ms': settled, 'handler_calls': handler_calls,
                  'total_calls': event_calls, 'before': before, 'after': after, 'events': events,
                  'groups': panel.model.rowCount(), 'source_members': len(source) if not isinstance(source,str) else None,
                  'members': sum(len(group.nodes) for group in panel.model._groups), 'instrumented': True,
                  'layouts': layouts}))
panel.stop(wait=True)
panel.close()
